const acct = "100032676";
const calls = {
  portfolio: tools.robinhood.get_portfolio({ account_number: acct }),
  optpos: tools.robinhood.get_option_positions({ account_number: acct }),
  optorders: tools.robinhood.get_option_orders({ account_number: acct }),
  eqpos: tools.robinhood.get_equity_positions({ account_number: acct }),
  upgrade: tools.robinhood.get_option_level_upgrade_info({ account_number: acct }),
  approval: tools.robinhood.get_trade_approval_setting({ account_number: acct }),
};
const keys = Object.keys(calls);
const res = await Promise.allSettled(Object.values(calls));
const out = {};
res.forEach((r, i) => out[keys[i]] = r.status === "fulfilled" ? r.value.data ?? r.value : { error: String(r.reason) });
return out;

const x = await search({ namespace: "x", query: "search recent posts", limit: 5 });
const f = await search({ namespace: "firecrawl", query: "search scrape", limit: 5 });
return { x: x.items.map(i => i.path + " :: " + i.signature.slice(0,600)), f: f.items.map(i => i.path + " :: " + i.signature.slice(0,600)) };

